// Builds the redesign's reusable uGUI pieces.
//
// Everything here is assembled from UiTheme values and the 9-slice shapes generated by
// GeneratedArt, so the screens stay free of literal colours and sizes. The shapes are cached
// per corner radius: a panel and a button of the same radius share one sprite and one atlas
// entry rather than each baking their own.
using System.Collections.Generic;
using DustZero.Game;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace DustZero.Editor
{
    public static class UiKit
    {
        /// <summary>
        /// The pack's rounded panel. Its 40px corner is 9-sliced, so one sprite serves every
        /// panel size; the radius argument older call sites pass is now only a hint for
        /// whether a capsule reads better.
        /// </summary>
        public static Sprite Rounded(float radius) => UiArt.Panel;

        /// <summary>The pack's capsule, for chips, pills and bars.</summary>
        public static Sprite Pill => UiArt.Pill;

        public static void ResetCache() => UiArt.ResetCache();

        // ------------------------------------------------------------------ primitives

        public static RectTransform Node(string name, Transform parent)
        {
            var go = new GameObject(name, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            return rt;
        }

        // 10.16-n is flat: no shadow band, no bevel, one hairline on ghost surfaces. The art
        // pack's panel_r40_shadow and btn_* faces bake the old bevel and its colours into the
        // image, so they cannot be re-tinted - these generated shapes are white and take
        // their colour from UiTheme instead.

        static Sprite _flatPanel, _flatButton, _flatButtonLine;

        /// <summary>White rounded 9-slice at the panel radius, cached for the whole build.</summary>
        internal static Sprite FlatPanelSprite =>
            _flatPanel ??= GeneratedArt.RoundedNineSlice("ui_flat_panel",
                Mathf.RoundToInt(UiTheme.PanelCorner));

        internal static Sprite FlatButtonSprite =>
            _flatButton ??= GeneratedArt.RoundedNineSlice("ui_flat_button",
                Mathf.RoundToInt(UiTheme.ButtonCorner));

        internal static Sprite FlatButtonOutline =>
            _flatButtonLine ??= GeneratedArt.RoundedOutlineNineSlice("ui_flat_button_line",
                Mathf.RoundToInt(UiTheme.ButtonCorner), Mathf.Max(1, Mathf.RoundToInt(UiTheme.HairLine)));

        /// <summary>A rounded, flat-coloured surface. No border, no gloss.</summary>
        public static Image Surface(string name, Transform parent, Color color, float radius,
                                    out RectTransform rt)
        {
            rt = Node(name, parent);
            var img = rt.gameObject.AddComponent<Image>();
            img.sprite = FlatPanelSprite;
            img.type = Image.Type.Sliced;
            img.color = color;
            img.raycastTarget = false;
            return img;
        }

        /// <summary>A content card: one flat rounded surface, tinted.</summary>
        public static Image Panel(string name, Transform parent, out RectTransform rt,
                                  Color? color = null, float? radius = null)
        {
            rt = Node(name, parent);
            var img = rt.gameObject.AddComponent<Image>();
            img.sprite = FlatPanelSprite;
            img.type = Image.Type.Sliced;
            img.color = color ?? UiTheme.Panel;
            img.raycastTarget = false;
            return img;
        }

        public static TextMeshProUGUI Label(string name, Transform parent, TMP_FontAsset font,
                                            float size, Color color, TextAlignmentOptions align,
                                            out RectTransform rt, string text = "")
        {
            rt = Node(name, parent);
            var tmp = rt.gameObject.AddComponent<TextMeshProUGUI>();
            tmp.font = font;
            tmp.fontSize = size;
            tmp.color = color;
            tmp.alignment = align;
            tmp.text = text;
            tmp.raycastTarget = false;
            tmp.textWrappingMode = TextWrappingModes.NoWrap;
            tmp.overflowMode = TextOverflowModes.Ellipsis;
            return tmp;
        }

        // ------------------------------------------------------------------ button

        /// <summary>
        /// A face-on-band button. <paramref name="height"/> drives the corner radius, and the
        /// root is grown to the 44pt minimum touch size when the face is smaller than that.
        /// </summary>
        public static UiButton Button(string name, Transform parent, TMP_FontAsset font,
                                      string text, UiButtonKind kind, out RectTransform rt,
                                      float? height = null, float? fontSize = null)
        {
            float h = height ?? UiTheme.ButtonTall;
            // Flat kinds hand null to Bind, so Repaint never touches the surface and the
            // caller's own plate (a translucent disc, a transparent tab) survives Awake.
            bool flat = kind == UiButtonKind.TextDanger || kind == UiButtonKind.Glass;

            rt = Node(name, parent);
            var button = rt.gameObject.AddComponent<UiButton>();

            var bg = rt.gameObject.AddComponent<Image>();
            bg.type = Image.Type.Sliced;
            bg.raycastTarget = true;
            bg.sprite = FlatButtonSprite;
            bg.color = flat ? new Color(0f, 0f, 0f, 0f) : UiTheme.ButtonFill(kind, UiButtonState.Normal);

            // The hairline on ghost surfaces is its own image: one alpha channel cannot carry
            // a fill and a differently coloured border at the same time.
            if (!flat && UiTheme.ButtonHasOutline(kind))
            {
                var line = Node("Line", rt);
                Stretch(line);
                var lineImg = line.gameObject.AddComponent<Image>();
                lineImg.sprite = FlatButtonOutline;
                lineImg.type = Image.Type.Sliced;
                lineImg.color = UiTheme.PanelLine;
                lineImg.raycastTarget = false;
            }

            // Everything that moves on a press lives under one child.
            var content = Node("Content", rt);
            Stretch(content);

            float labelSize = fontSize ?? UiTheme.Body;
            var label = Label("Label", content, font, labelSize, Color.white,
                              TextAlignmentOptions.Center, out var lrt, text);
            Stretch(lrt, UiTheme.S8);
            // Never squeeze the label below one line box, or it renders nothing at all.
            float vPad = Mathf.Max(0f, Mathf.Min(UiTheme.S8, (h - UiTheme.Line(labelSize)) * 0.5f));
            lrt.offsetMin = new Vector2(UiTheme.S8, vPad);
            lrt.offsetMax = new Vector2(-UiTheme.S8, -vPad);

            float subBand = UiTheme.Line(UiTheme.Caption);
            var sub = Label("Sub", content, font, UiTheme.Caption, Color.white,
                            TextAlignmentOptions.Center, out var subRt);
            Anchor(subRt, new Vector2(0f, 0f), new Vector2(1f, 0f),
                   new Vector2(UiTheme.S8, UiTheme.S4), new Vector2(-UiTheme.S8, UiTheme.S4 + subBand));
            sub.gameObject.SetActive(false);

            var padlockRt = Node("Lock", content);
            Anchor(padlockRt, new Vector2(0f, 0.5f), new Vector2(0f, 0.5f),
                   new Vector2(UiTheme.S10, -UiTheme.Py(11f)),
                   new Vector2(UiTheme.S10 + UiTheme.Px(22f), UiTheme.Py(11f)));
            var padlock = padlockRt.gameObject.AddComponent<Image>();
            padlock.sprite = UiArt.Icon("lock");
            padlock.color = UiTheme.Ink3;
            padlock.preserveAspect = true;
            padlock.raycastTarget = false;
            padlockRt.gameObject.SetActive(false);

            var dot = Dot("Dot", rt);
            Anchor(dot, Vector2.one, Vector2.one,
                   new Vector2(-UiTheme.BadgeDot * 0.6f, -UiTheme.BadgeDot * 0.6f),
                   new Vector2(UiTheme.BadgeDot * 0.4f, UiTheme.BadgeDot * 0.4f));
            dot.gameObject.SetActive(false);

            // One shape for every state; UiButton recolours it rather than swapping faces.
            button.Bind(flat ? null : bg, FlatButtonSprite, FlatButtonSprite, FlatButtonSprite,
                        FlatButtonSprite, content, label, sub, null,
                        padlockRt.gameObject, dot.gameObject, kind);
            button.SetSubBand(UiTheme.S4 + subBand);
            return button;
        }

        /// <summary>The pack's file suffix for a button kind.</summary>
        static string FaceName(UiButtonKind kind) => kind switch
        {
            UiButtonKind.Primary => "primary",
            UiButtonKind.Navy => "navy",
            UiButtonKind.Success => "success",
            UiButtonKind.Icon => "panel",
            _ => "secondary",
        };

        // ------------------------------------------------------------------ chips and badges

        /// <summary>
        /// A pill holding a value, used for currency, counts and conditions. Returns the value
        /// label so the caller can update the number without re-reading the hierarchy.
        /// </summary>
        public static TextMeshProUGUI Chip(string name, Transform parent, TMP_FontAsset font,
                                           string text, out RectTransform rt,
                                           Color? fill = null, Color? ink = null,
                                           float? height = null, float? fontSize = null)
        {
            float h = height ?? UiTheme.Touch;
            rt = Node(name, parent);
            var bg = rt.gameObject.AddComponent<Image>();
            bg.sprite = UiArt.Pill;
            bg.type = Image.Type.Sliced;
            bg.color = fill ?? UiTheme.Panel;
            bg.raycastTarget = false;

            // Pad horizontally only, and never let the label box fall below one line: a chip
            // shorter than the font's line height renders empty instead of clipped.
            float size = fontSize ?? UiTheme.LabelSize;
            var label = Label("Value", rt, font, size, ink ?? UiTheme.Ink,
                              TextAlignmentOptions.Center, out var lrt, text);
            float band = Mathf.Max(UiTheme.Line(size), h - UiTheme.S4) * 0.5f;
            Anchor(lrt, new Vector2(0f, 0.5f), new Vector2(1f, 0.5f),
                   new Vector2(UiTheme.S10, -band), new Vector2(-UiTheme.S10, band));
            return label;
        }

        /// <summary>The red notification dot with its white ring.</summary>
        public static RectTransform Dot(string name, Transform parent)
        {
            var ring = Node(name, parent);
            // The pack draws the dot with its white ring already in place.
            var ringImg = ring.gameObject.AddComponent<Image>();
            ringImg.sprite = UiArt.BadgeDot;
            ringImg.color = Color.white;
            ringImg.raycastTarget = false;
            ring.sizeDelta = new Vector2(UiTheme.BadgeDot + UiTheme.BadgeRing * 2f,
                                         UiTheme.BadgeDot + UiTheme.BadgeRing * 2f);
            return ring;
        }

        /// <summary>A small rounded rectangle for "Lv.7" or "무료".</summary>
        public static TextMeshProUGUI InfoBadge(string name, Transform parent, TMP_FontAsset font,
                                                string text, Color fill, out RectTransform rt)
        {
            rt = Node(name, parent);
            var bg = rt.gameObject.AddComponent<Image>();
            bg.sprite = UiArt.Pill;
            bg.type = Image.Type.Sliced;
            bg.color = fill;
            bg.raycastTarget = false;
            // Tall enough for its own text: the guide's 16pt badge is a minimum, not a cap.
            float badgeSize = UiTheme.Caption * 0.8f;
            float badgeH = Mathf.Max(UiTheme.BadgeInfo, UiTheme.Line(badgeSize) + UiTheme.S4);
            rt.sizeDelta = new Vector2(rt.sizeDelta.x, badgeH);

            var label = Label("Text", rt, font, badgeSize, Color.white,
                              TextAlignmentOptions.Center, out var lrt, text);
            Anchor(lrt, new Vector2(0f, 0.5f), new Vector2(1f, 0.5f),
                   new Vector2(UiTheme.S6, -badgeH * 0.5f), new Vector2(-UiTheme.S6, badgeH * 0.5f));
            return label;
        }

        /// <summary>
        /// A progress bar with rounded ends. The fill is masked rather than Image.Filled so the
        /// rounded cap survives at low percentages, which the guide calls for explicitly.
        /// </summary>
        public static RectTransform Bar(string name, Transform parent, Color track, Color fill,
                                        float height, out RectTransform fillRect)
        {
            var rt = Node(name, parent);
            rt.sizeDelta = new Vector2(rt.sizeDelta.x, height);

            var bg = rt.gameObject.AddComponent<Image>();
            bg.sprite = UiArt.Bar;
            bg.type = Image.Type.Sliced;
            bg.color = track;
            bg.raycastTarget = false;

            var mask = Node("Mask", rt);
            Stretch(mask);
            mask.gameObject.AddComponent<RectMask2D>();

            fillRect = Node("Fill", mask);
            var fillImg = fillRect.gameObject.AddComponent<Image>();
            fillImg.sprite = UiArt.Bar;
            fillImg.type = Image.Type.Sliced;
            fillImg.color = fill;
            fillImg.raycastTarget = false;
            Anchor(fillRect, Vector2.zero, new Vector2(0f, 1f), Vector2.zero, Vector2.zero);
            fillRect.sizeDelta = new Vector2(0f, 0f);
            fillRect.anchorMax = new Vector2(1f, 1f);
            return rt;
        }


        // ------------------------------------------------------------------ redesign pieces

        /// <summary>
        /// A bottom-nav item: icon above label, no button chrome at all. The mockup's bar is a
        /// flat white strip - wrapping each tab in a face-and-edge button, as a first pass did,
        /// reads as five cards instead of a navigation bar.
        /// </summary>
        public static UiButton NavItem(string name, Transform parent, TMP_FontAsset font,
                                       Sprite icon, string label, out RectTransform rt,
                                       out Image iconImage, out TextMeshProUGUI labelText,
                                       out Image indicator)
        {
            rt = Node(name, parent);
            var button = rt.gameObject.AddComponent<UiButton>();

            var hit = rt.gameObject.AddComponent<Image>();
            hit.color = new Color(0f, 0f, 0f, 0f);
            hit.raycastTarget = true;

            // A layout group owns this item's own position, so the press offset must move a
            // child instead. Writing to the item itself would undo the layout on every
            // repaint and leave the whole bar sitting above its strip.
            var content = Node("Content", rt);
            Stretch(content);

            // 10.16-n marks the chosen tab with a filled rounded plate behind the whole item
            // (measured #2A3136, 10px radius), not with a bar hanging off the top edge. It is
            // the first child so the icon and label draw over it.
            indicator = Surface("Indicator", content, UiTheme.DarkPanel2, UiTheme.ButtonCorner,
                                out var indRt);
            Stretch(indRt, UiTheme.S4);

            // Measured in the bar: a 26px icon near the top and an 11.5px label at the
            // bottom of a 78px strip. The old point-based sizes were a third too large for
            // the corrected bar height and ran the label through the icon.
            float iconSize = UiTheme.Py(26f);
            var iconRt = Node("Icon", content);
            Anchor(iconRt, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f),
                   new Vector2(-iconSize * 0.5f, -UiTheme.Py(5f) - iconSize),
                   new Vector2(iconSize * 0.5f, -UiTheme.Py(5f)));
            iconImage = iconRt.gameObject.AddComponent<Image>();
            iconImage.sprite = icon;
            iconImage.preserveAspect = true;
            iconImage.raycastTarget = false;

            float navLabel = UiTheme.Py(11.5f);
            labelText = Label("Label", content, font, navLabel, UiTheme.DarkInk2,
                              TextAlignmentOptions.Center, out var lrt, label);
            labelText.textWrappingMode = TextWrappingModes.NoWrap;
            // 바닥에서 8px. 원본을 재면 글자 아래 여백이 8 이고 우리는 4.2 였다 —
            // 탭 글자 여섯 개가 전부 4.6px 아래에 찍혔다. 한 개만 보면 모른다.
            float navLabelFoot = UiTheme.Py(8f);
            Anchor(lrt, new Vector2(0f, 0f), new Vector2(1f, 0f),
                   new Vector2(0f, navLabelFoot),
                   new Vector2(0f, navLabelFoot + UiTheme.Line(navLabel)));

            // The icon is finished colour art, so it is deliberately NOT handed to Bind:
            // UiButton tints whatever icon it is given, which would flatten these to one
            // colour. Only the label changes between states.
            button.Bind(null, null, null, null, null, content, labelText, null, null,
                        null, null, UiButtonKind.Nav);
            return button;
        }

        /// <summary>A currency readout: round icon, then the number, on a white pill.</summary>
        public static TextMeshProUGUI CurrencyChip(string name, Transform parent, TMP_FontAsset font,
                                                   Sprite icon, Color iconTint, string text,
                                                   out RectTransform rt, float? height = null)
        {
            float h = height ?? UiTheme.Touch;
            rt = Node(name, parent);
            var bg = rt.gameObject.AddComponent<Image>();
            bg.sprite = UiArt.Pill;
            bg.type = Image.Type.Sliced;
            bg.color = UiTheme.Panel;
            bg.raycastTarget = false;

            float pip = h * 0.62f;
            var iconRt = Node("Icon", rt);
            Anchor(iconRt, new Vector2(0f, 0.5f), new Vector2(0f, 0.5f),
                   new Vector2(UiTheme.S6, -pip * 0.5f), new Vector2(UiTheme.S6 + pip, pip * 0.5f));
            var img = iconRt.gameObject.AddComponent<Image>();
            img.sprite = icon;
            img.color = iconTint;
            img.preserveAspect = true;
            img.raycastTarget = false;

            var label = Label("Value", rt, font, UiTheme.LabelSize, UiTheme.Ink,
                              TextAlignmentOptions.Right, out var lrt, text);
            float band = Mathf.Max(UiTheme.Line(UiTheme.LabelSize), h - UiTheme.S4) * 0.5f;
            Anchor(lrt, new Vector2(0f, 0.5f), new Vector2(1f, 0.5f),
                   new Vector2(UiTheme.S6 + pip + UiTheme.S4, -band),
                   new Vector2(-UiTheme.S12, band));
            return label;
        }

        /// <summary>A side-rail card: icon over a short label, on a white rounded square.</summary>
        public static UiButton RailCard(string name, Transform parent, TMP_FontAsset font,
                                        Sprite icon, string label, out RectTransform rt,
                                        out Image iconImage)
        {
            float size = UiTheme.Px(58f);
            rt = Node(name, parent);
            var button = rt.gameObject.AddComponent<UiButton>();

            var face = rt.gameObject.AddComponent<Image>();
            face.sprite = UiArt.Faces("panel").Normal;
            face.type = Image.Type.Sliced;
            face.raycastTarget = true;

            // Same reason as NavItem: the side rail is a layout group, so only a child moves.
            var content = Node("Content", rt);
            Stretch(content);

            float iconSize = UiTheme.Px(26f);
            var iconRt = Node("Icon", content);
            Anchor(iconRt, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f),
                   new Vector2(-iconSize * 0.5f, -UiTheme.S8 - iconSize),
                   new Vector2(iconSize * 0.5f, -UiTheme.S8));
            iconImage = iconRt.gameObject.AddComponent<Image>();
            iconImage.sprite = icon;
            iconImage.color = UiTheme.Ink;
            iconImage.preserveAspect = true;
            iconImage.raycastTarget = false;

            var text = Label("Label", content, font, UiTheme.Caption * 0.9f, UiTheme.Ink,
                             TextAlignmentOptions.Center, out var lrt, label);
            Anchor(lrt, new Vector2(0f, 0f), new Vector2(1f, 0f),
                   new Vector2(0f, UiTheme.S6), new Vector2(0f, UiTheme.S6 + UiTheme.Line(UiTheme.Caption * 0.9f)));

            var railFaces = UiArt.Faces("panel");
            button.Bind(face, railFaces.Normal, railFaces.Pressed, railFaces.Disabled,
                        railFaces.Selected, content, text, null, iconImage, null, null,
                        UiButtonKind.Icon);
            return button;
        }

        // ------------------------------------------------------------------ layout

        /// <summary>
        /// 스크롤 뷰포트가 드래그와 휠을 받게 하는 **보이지 않는 받이**.
        ///
        /// ScrollRect 는 EventSystem 이 레이캐스트로 맞힌 것에서만 드래그를 받는다.
        /// 뷰포트에 그래픽이 하나도 없으면 카드 **위**에서만 스크롤되고 카드 사이
        /// 빈 자리나 휠은 아무 데도 닿지 않는다. 실제로 로비 탭 여섯 개가 그랬다.
        ///
        /// 알파 0 이어도 raycastTarget 이 켜져 있으면 받는다. 그려지는 것은 없다.
        /// </summary>
        public static Image ScrollCatcher(RectTransform viewport)
        {
            var img = viewport.GetComponent<Image>();
            if (img != null)
            {
                // 이미 바탕이 있으면 그 색을 건드리지 않는다. 레이캐스트만 켜면 된다.
                img.raycastTarget = true;
                return img;
            }
            img = viewport.gameObject.AddComponent<Image>();
            img.color = new Color(0f, 0f, 0f, 0f);
            img.raycastTarget = true;
            return img;
        }

        public static void Stretch(RectTransform rt, float pad = 0f)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = new Vector2(pad, pad);
            rt.offsetMax = new Vector2(-pad, -pad);
        }

        public static void Anchor(RectTransform rt, Vector2 min, Vector2 max,
                                  Vector2 offMin, Vector2 offMax)
        {
            rt.anchorMin = min;
            rt.anchorMax = max;
            rt.offsetMin = offMin;
            rt.offsetMax = offMax;
        }

        /// <summary>A horizontal row with the 4pt-scale gap the guide uses between controls.</summary>
        public static HorizontalLayoutGroup Row(RectTransform rt, float spacing,
                                                TextAnchor align = TextAnchor.MiddleLeft)
        {
            var layout = rt.gameObject.AddComponent<HorizontalLayoutGroup>();
            layout.spacing = spacing;
            layout.childAlignment = align;
            layout.childForceExpandWidth = false;
            layout.childForceExpandHeight = false;
            layout.childControlWidth = true;
            layout.childControlHeight = true;
            return layout;
        }
    }
}
